import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import { ID } from 'appwrite';
import { User, UserPayload } from '@/types/user';
import { Session } from '@/types/session';
import { SessionService } from '@/services/session.service';
import { UserService } from '@/services/user.service';
import { account } from '@/lib/appwrite';

interface AuthState {
    user: User | null;
    session: Session | null;
    userId: string | null;
    loading: boolean;
    error: string | null;
    initialized: boolean;
}

const initialState: AuthState = {
    user: null,
    session: null,
    userId: null,
    loading: false,
    error: null,
    initialized: false,
};

// Async Thunks
export const checkSession = createAsyncThunk(
    'auth/checkSession',
    async (_, { rejectWithValue }) => {
        try {
            // 1. Appwrite Account (Anonymous or otherwise)
            let currentUserId: string;
            try {
                const session = await account.getSession('current');
                currentUserId = session.userId;
            } catch {
                const session = await account.createAnonymousSession();
                currentUserId = session.userId;
            }

            // 2. User Document
            let userDoc: User;
            try {
                userDoc = await UserService.get(currentUserId);
            } catch {
                const payload: UserPayload = {
                    userId: currentUserId,
                    username: `Guest-${currentUserId.substring(0, 5)}`,
                    isGuest: true,
                };
                userDoc = await UserService.create(payload);
            }

            // 3. Custom Session Check
            let customSession: Session | null = null;
            const storedSessionId = localStorage.getItem('nexconnect_session_id');
            if (storedSessionId) {
                try {
                    const restored = await SessionService.get(storedSessionId);
                    if (restored.isActive && new Date(restored.expiresAt) > new Date()) {
                        customSession = restored;
                    } else {
                        localStorage.removeItem('nexconnect_session_id');
                        localStorage.removeItem('nexconnect_private_id');
                    }
                } catch {
                    localStorage.removeItem('nexconnect_session_id');
                    localStorage.removeItem('nexconnect_private_id');
                }
            }

            return { userId: currentUserId, user: userDoc, session: customSession };

        } catch (error: any) {
            return rejectWithValue(error.message || 'Auth initialization failed');
        }
    }
);

export const login = createAsyncThunk(
    'auth/login',
    async (username: string, { getState, rejectWithValue }) => {
        try {
            const state = (getState() as any).auth;
            const userId = state.userId;

            if (!userId) throw new Error("Authentication not ready");

            const privateId = ID.unique();
            const sessionPayload = {
                userId,
                privateId,
                expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
            };
            const newSession = await SessionService.create(sessionPayload);

            localStorage.setItem('nexconnect_session_id', newSession.$id);
            localStorage.setItem('nexconnect_private_id', privateId);

            // Update Username
            await UserService.update(userId, { username });
            // Fetch updated user to be sure
            const updatedUser = await UserService.get(userId);

            return { session: newSession, user: updatedUser };
        } catch (error: any) {
            return rejectWithValue(error.message || 'Login failed');
        }
    }
);

export const logout = createAsyncThunk(
    'auth/logout',
    async (_, { getState, rejectWithValue }) => {
        try {
            const state = (getState() as any).auth;
            if (state.session) {
                await SessionService.expire(state.session.$id);
            }
            localStorage.removeItem('nexconnect_session_id');
            localStorage.removeItem('nexconnect_private_id');
            return null;
        } catch (error: any) {
            return rejectWithValue(error.message || 'Logout failed');
        }
    }
);

const authSlice = createSlice({
    name: 'auth',
    initialState,
    reducers: {
        clearError: (state) => {
            state.error = null;
        }
    },
    extraReducers: (builder) => {
        // initAuth / checkSession
        builder.addCase(checkSession.pending, (state) => {
            state.loading = true;
            state.error = null;
        });
        builder.addCase(checkSession.fulfilled, (state, action) => {
            state.loading = false;
            state.userId = action.payload.userId;
            state.user = action.payload.user;
            state.session = action.payload.session;
            state.initialized = true;
        });
        builder.addCase(checkSession.rejected, (state, action) => {
            state.loading = false;
            state.initialized = true; // Still initialized, just failed to get session maybe
            // Keep user/userId null if catastrophic failure
            state.error = action.payload as string;
        });

        // Login
        builder.addCase(login.pending, (state) => {
            state.loading = true;
            state.error = null;
        });
        builder.addCase(login.fulfilled, (state, action) => {
            state.loading = false;
            state.session = action.payload.session;
            state.user = action.payload.user;
        });
        builder.addCase(login.rejected, (state, action) => {
            state.loading = false;
            state.error = action.payload as string;
        });

        // Logout
        builder.addCase(logout.fulfilled, (state) => {
            state.session = null;
            // User and userId technically remain (Anonymous Appwrite session persists)
            // But from "App Session" pov, we are done.
        });
    },
});

export const { clearError } = authSlice.actions;
export default authSlice.reducer;
