import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import { Room, RoomPayload } from '@/types/room';
import { RoomMember, RoomMemberPayload } from '@/types/room-member';
import { RoomService } from '@/services/room.service';
import { RoomMemberService } from '@/services/room-member.service';


interface RoomState {
    rooms: Room[];
    currentRoom: Room | null;
    members: RoomMember[];
    loading: boolean;
    error: string | null;
}

const initialState: RoomState = {
    rooms: [],
    currentRoom: null,
    members: [],
    loading: false,
    error: null,
};

// Async Thunks
export const fetchRooms = createAsyncThunk(
    'rooms/fetchRooms',
    async (search: string | undefined, { rejectWithValue }) => {
        try {
            const response = await RoomService.list(search);
            return response.documents;
        } catch (error: any) {
            return rejectWithValue(error.message || 'Failed to fetch rooms');
        }
    }
);

export const createRoom = createAsyncThunk(
    'rooms/createRoom',
    async (payload: RoomPayload, { rejectWithValue }) => {
        try {
            const room = await RoomService.create(payload);
            return room;
        } catch (error: any) {
            return rejectWithValue(error.message || 'Failed to create room');
        }
    }
);

export const enterRoom = createAsyncThunk(
    'rooms/enterRoom',
    async (roomId: string, { rejectWithValue }) => {
        try {
            const room = await RoomService.get(roomId);
            const membersResponse = await RoomMemberService.list(roomId);
            return { room, members: membersResponse.documents };
        } catch (error: any) {
            return rejectWithValue(error.message || 'Failed to enter room');
        }
    }
);

export const joinRoom = createAsyncThunk(
    'rooms/joinRoom',
    async (payload: RoomMemberPayload, { getState, rejectWithValue }) => {
        try {
            const state = getState() as { rooms: RoomState };
            const { members, currentRoom } = state.rooms;

            // Duplicate Prevention Guard
            // Only effective if we are strictly joining the CURRENT room we are looking at.
            // If joining a room from the list without entering, we might not have members loaded.
            // However, the prompt implies "enter -> join" flow or ensuring we don't double join.
            // If currentRoom matches, we check.

            if (currentRoom && currentRoom.$id === payload.room) {
                const isAlreadyMember = members.some(m =>
                    m.user.$id === payload.user && m.isActive
                );

                if (isAlreadyMember) {
                    // Already a member, no op, or return existing (optional)
                    // We can return null or reject to indicate "already joined" but success
                    // Let's just return undefined to skip adding
                    return null;
                }
            }

            // If not loaded or not found, proceed to add
            // Note: Parallel requests could still race here, but this catches UI double-clicks.

            const member = await RoomMemberService.add(payload);
            return member;
        } catch (error: any) {
            return rejectWithValue(error.message || 'Failed to join room');
        }
    }
);

export const leaveRoom = createAsyncThunk(
    'rooms/leaveRoom',
    async (memberId: string, { rejectWithValue }) => {
        try {
            await RoomMemberService.kick(memberId);
            return memberId;
        } catch (error: any) {
            return rejectWithValue(error.message || 'Failed to leave room');
        }
    }
);

const roomSlice = createSlice({
    name: 'rooms',
    initialState,
    reducers: {
        clearRoomError: (state) => {
            state.error = null;
        },
        exitRoom: (state) => {
            state.currentRoom = null;
            state.members = [];
        },
        addRoom: (state, action) => {
            state.rooms.unshift(action.payload);
        },
        updateRoom: (state, action) => {
            const index = state.rooms.findIndex(r => r.$id === action.payload.$id);
            if (index !== -1) {
                state.rooms[index] = action.payload;
            }
            if (state.currentRoom && state.currentRoom.$id === action.payload.$id) {
                state.currentRoom = action.payload;
            }
        },
        deleteRoom: (state, action) => {
            state.rooms = state.rooms.filter(r => r.$id !== action.payload.$id);
            if (state.currentRoom && state.currentRoom.$id === action.payload.$id) {
                state.currentRoom = null;
                state.members = [];
            }
        },
        addMember: (state, action) => {
            // Check if already exists to be safe
            if (!state.members.find(m => m.$id === action.payload.$id)) {
                state.members.push(action.payload);
            }
        },
        updateMember: (state, action) => {
            const index = state.members.findIndex(m => m.$id === action.payload.$id);
            if (index !== -1) {
                state.members[index] = action.payload;
            }
        },
        removeMember: (state, action) => {
            state.members = state.members.filter(m => m.$id !== action.payload.$id);
        }
    },
    extraReducers: (builder) => {
        // Fetch Rooms
        builder.addCase(fetchRooms.pending, (state) => {
            state.loading = true;
            state.error = null;
        });
        builder.addCase(fetchRooms.fulfilled, (state, action) => {
            state.loading = false;
            state.rooms = action.payload;
        });
        builder.addCase(fetchRooms.rejected, (state, action) => {
            state.loading = false;
            state.error = action.payload as string;
        });

        // Create Room
        builder.addCase(createRoom.fulfilled, (state, action) => {
            state.rooms.unshift(action.payload);
        });

        // Enter Room
        builder.addCase(enterRoom.pending, (state) => {
            state.loading = true;
            state.error = null;
        });
        builder.addCase(enterRoom.fulfilled, (state, action) => {
            state.loading = false;
            state.currentRoom = action.payload.room;
            state.members = action.payload.members;
        });
        builder.addCase(enterRoom.rejected, (state, action) => {
            state.loading = false;
            state.error = action.payload as string;
        });

        // Join Room
        builder.addCase(joinRoom.fulfilled, (state, action) => {
            if (action.payload) {
                state.members.push(action.payload);
            }
        });

        // Leave Room
        builder.addCase(leaveRoom.fulfilled, (state, action) => {
            state.members = state.members.filter(m => m.$id !== action.payload);
        });
    },
});

export const { clearRoomError, exitRoom, addRoom, updateRoom, deleteRoom, addMember, updateMember, removeMember } = roomSlice.actions;
export default roomSlice.reducer;
